INSERT INTO public."tasks" ("id", "assignee_id", "created_at", "updated_at", "title", "description", "priority", "status", "submission_link", "publish_date", "client_id", "is_archived", "feedback", "progress_note", "drive_link", "content_type", "content_description", "completion_note", "is_deliverable", "publish_notes", "estimated_time_minutes", "deliverable_month", "deliverable_type", "due_date", "creator_id") VALUES ('4085cfe6-022f-4616-9f67-534c9707dcf7', NULL, '2026-09-07T09:49:31.272152+00:00', '2026-09-09T14:07:15.231+00:00', 'فيديو سفاري', 'الطالبة تدخل المكتب:
— السلام عليكم.

صاحب المكتب:
— وعليكم السلام، اتفضلي.

الطالبة:
— هو حضرتك بتطلع باصات للجامعة؟

صاحب المكتب:
— أيوه طبعًا.

الطالبة:
— طيب ممكن أعرف إيه المميزات عندكم؟

صاحب المكتب:
— عندنا مميزات كتير، أهمها إن عندنا مواعيد مختلفة في الذهاب والعودة، يعني عندنا ميعادين في الذهاب و3 مواعيد في العودة، عشان تختاري الميعاد اللي يناسب جدولك.

الطالبة:
— طب ونظام الاشتراك عندكم عامل إزاي؟

صاحب المكتب:
— عندنا أكتر من نظام، عشان كل طالب يختار اللي يناسبه:
اشتراك يومي، وباقة 30، وباقة 40، وكمان نظام الترب.

الطالبة:
— يعني أنا أقدر أختار النظام المناسب ليا؟

صاحب المكتب:
— طبعًا، وكل نظام بيكون باسم الطالب وبياناته، عشان كل حاجة تبقى منظمة وواضحة.

الطالبة:
— طيب ولو حصلت مشكلة أو احتجت حاجة وأنا في الطريق؟

صاحب المكتب:
— هنا بقى أهم حاجة عندنا… المتابعة المستمرة مع الطالب.
من أول الاشتراك وإنتِ مش لوحدك، فيه متابعة وتنظيم وتواصل مستمر.

الطالبة:
— بصراحة كده الموضوع مش مجرد باص 😂

صاحب المكتب:
— بالظبط… إحنا مش بنبيعلك مشوار، إحنا بنوفرلك خدمة كاملة ومتابعة وراحة بال.

🎬 النهاية — لقطة للمكتب والباص/اللوجو:

«سفاري 🚌
مواعيد تناسبك • أنظمة اشتراك مختلفة • متابعة مستمرة
كل ده… عشان مشوار جامعتك يبقى أسهل وأضمن.', 'medium', 'todo', NULL, NULL, NULL, FALSE, NULL, NULL, 'https://drive.google.com/drive/folders/1XpmBiGLeRKs9DZHdV5WP6cDerqjG6XX8', NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, '2026-09-08T23:59:00+00:00', '58858b4b-5860-416e-8bd8-110ae8d4e30c') ON CONFLICT DO NOTHING;
